// Dimensiones y silueta real medidas sobre el canal alfa de cada sprite de combate.
// cx       = centro horizontal del cuerpo [0..1]
// w        = ancho efectivo del cuerpo (percentil 5-95, excluye puntas de armas) [0..1]
// headTopY = parte superior de la cabeza sobre la linea hx [0..1]
// bodyBotY = borde inferior visible del cuerpo [0..1]
// contour  = 16 pares [leftX, rightX] normalizados [0..1] desde headTopY hasta bodyBotY
export interface SpriteBounds {
  cx: number;
  w: number;
  headTopY: number;
  bodyBotY: number;
  contour: readonly (readonly [number, number])[];
}

